mapper.sql:
where s.clan_id=#{criteria.clanId} and s.deleted_at is null
  and (s.branch_id is null or s.branch_id in #{id})and s.branch_id is null
  and ((s.privacy_level not in ('relatives_only','private','sealed') and s.sensitive_level not in ('sensitive','highly_sensitive')) or s.created_by=#{criteria.actorId} or s.branch_id in #{id})
  and (lower(coalesce(s.site_name,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(s.address_text,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(s.founded_period,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(s.current_status,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(s.summary,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(s.description,'')) like concat('%',lower(#{criteria.keyword}),'%'))
  and s.site_type in #{v}
  and s.branch_id in #{v}
  and s.related_person_id=#{criteria.relatedPersonId}
  and s.data_status in #{v}
  and s.privacy_level=#{criteria.privacyLevel}and s.is_featured_on_home=#{criteria.featuredOnHome}
  and lower(coalesce(s.address_text,'')) like concat('%',lower(#{criteria.addressText}),'%')
  and lower(coalesce(s.founded_period,'')) like concat('%',lower(#{criteria.foundedPeriod}),'%')
  and lower(coalesce(s.current_status,'')) like concat('%',lower(#{criteria.currentStatus}),'%')
